-- Per-study preview image (infographic) shown on list cards and detail pages.
-- preview_image_path: path inside the public 'studies' storage bucket
-- preview_image_source: where the image came from ('pdf_figure' | 'url_scrape' | 'ai_dataviz' | 'ai_generated' | 'manual')
-- preview_image_caption: text shown under the image
-- preview_image_is_ai: true when the image was generated by AI (not from the source)

alter table public.studies
  add column if not exists preview_image_path text,
  add column if not exists preview_image_source text,
  add column if not exists preview_image_caption text,
  add column if not exists preview_image_is_ai boolean not null default false;
